{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-05-11 13:15:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of your hospital doctors. I know you’re here for your stem cell transplant. How are you feeling today?"
    },
    {
      "turn_number": 2,
      "time": "2156-05-11 13:16:00",
      "speaker": "Patient",
      "text": "Hi, Dr. Lee. I’m a little anxious, but otherwise okay. I just want to get through this transplant safely."
    },
    {
      "turn_number": 3,
      "time": "2156-05-11 13:17:00",
      "speaker": "Doctor",
      "text": "That’s completely understandable. We’re going to take good care of you. First, we’ll place a central line so we can give your medications and draw blood easily."
    },
    {
      "turn_number": 4,
      "time": "2156-05-11 13:18:00",
      "speaker": "Patient",
      "text": "I remember that from last time. The one in my neck? Is it the same kind?"
    },
    {
      "turn_number": 5,
      "time": "2156-05-11 13:19:00",
      "speaker": "Doctor",
      "text": "Yes, a triple-lumen catheter in your left internal jugular. It’s already been placed successfully. You’ll have it for the whole stay."
    },
    {
      "turn_number": 6,
      "time": "2156-05-11 13:20:00",
      "speaker": "Patient",
      "text": "Good. I was worried about that. What’s next?"
    },
    {
      "turn_number": 7,
      "time": "2156-05-11 13:21:00",
      "speaker": "Doctor",
      "text": "We’ll start your conditioning chemotherapy tomorrow—fludarabine and busulfan. It prepares your body to accept the donor stem cells."
    },
    {
      "turn_number": 8,
      "time": "2156-05-11 13:22:00",
      "speaker": "Patient",
      "text": "And the transplant itself? When does that happen?"
    },
    {
      "turn_number": 9,
      "time": "2156-05-11 13:23:00",
      "speaker": "Doctor",
      "text": "That’s scheduled for day 6 of your admission—so around May 17th. The stem cells will be infused through your central line."
    },
    {
      "turn_number": 10,
      "time": "2156-05-11 13:24:00",
      "speaker": "Patient",
      "text": "Okay. And I’m still on vancomycin for C. diff—will I keep that?"
    },
    {
      "turn_number": 11,
      "time": "2156-05-11 13:25:00",
      "speaker": "Doctor",
      "text": "Yes, we’re continuing your oral vancomycin throughout your stay because of your weakened immune system. We don’t want the infection to come back."
    },
    {
      "turn_number": 12,
      "time": "2156-05-11 13:26:00",
      "speaker": "Patient",
      "text": "Makes sense. My blood sugars have been high lately—will that be watched?"
    },
    {
      "turn_number": 13,
      "time": "2156-05-11 13:27:00",
      "speaker": "Doctor",
      "text": "Yes, the diabetes team will help manage that. You’re already on insulin and metformin, and we’ll adjust doses as needed."
    },
    {
      "turn_number": 14,
      "time": "2156-05-12 10:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re starting your chemotherapy today—fludarabine and busulfan. This will last a few days."
    },
    {
      "turn_number": 15,
      "time": "2156-05-12 10:01:00",
      "speaker": "Patient",
      "text": "Any side effects I should watch for?"
    },
    {
      "turn_number": 16,
      "time": "2156-05-12 10:02:00",
      "speaker": "Doctor",
      "text": "Fatigue, nausea, and low blood counts are common. We’ll monitor you closely. We’ve also started prophylactic medications to prevent infections."
    },
    {
      "turn_number": 17,
      "time": "2156-05-12 10:03:00",
      "speaker": "Patient",
      "text": "Like the atovaquone and acyclovir I take at home?"
    },
    {
      "turn_number": 18,
      "time": "2156-05-12 10:04:00",
      "speaker": "Doctor",
      "text": "Exactly. You’re on those, plus others to prevent lung infections and herpes reactivation."
    },
    {
      "turn_number": 19,
      "time": "2156-05-13 09:30:00",
      "speaker": "Doctor",
      "text": "Your labs show your white count is dropping, which is expected. We’ve started filgrastim to help your neutrophils recover later."
    },
    {
      "turn_number": 20,
      "time": "2156-05-13 09:31:00",
      "speaker": "Patient",
      "text": "So I’m more at risk for infections now?"
    },
    {
      "turn_number": 21,
      "time": "2156-05-13 09:32:00",
      "speaker": "Doctor",
      "text": "Yes, so we’re keeping you in protective isolation. No fresh flowers or raw foods, and we’ll screen visitors."
    },
    {
      "turn_number": 22,
      "time": "2156-05-14 14:00:00",
      "speaker": "Patient",
      "text": "I’ve been a bit nauseous. Is that from the chemo?"
    },
    {
      "turn_number": 23,
      "time": "2156-05-14 14:01:00",
      "speaker": "Doctor",
      "text": "Very likely. We’ll increase your ondansetron and add another anti-nausea med. Make sure to drink fluids."
    },
    {
      "turn_number": 24,
      "time": "2156-05-15 11:00:00",
      "speaker": "Doctor",
      "text": "Your blood counts are very low, as expected. No signs of infection so far—your CMV test was negative today."
    },
    {
      "turn_number": 25,
      "time": "2156-05-15 11:01:00",
      "speaker": "Patient",
      "text": "That’s good. I’ve been worried about CMV with my immune deficiency."
    },
    {
      "turn_number": 26,
      "time": "2156-05-15 11:02:00",
      "speaker": "Doctor",
      "text": "We’re monitoring weekly. You’re also on fluconazole to prevent fungal infections, which we’ll continue after transplant."
    },
    {
      "turn_number": 27,
      "time": "2156-05-17 10:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day—we’re going to infuse your donor stem cells. You’ve been randomized to a study with tacrolimus, sirolimus, and bortezomib to prevent graft-versus-host disease."
    },
    {
      "turn_number": 28,
      "time": "2156-05-17 10:01:00",
      "speaker": "Patient",
      "text": "Will I feel anything during the infusion?"
    },
    {
      "turn_number": 29,
      "time": "2156-05-17 10:02:00",
      "speaker": "Doctor",
      "text": "Most patients don’t. We’ll monitor your vital signs closely. The stem cells will find their way to your bone marrow and start making new blood cells."
    },
    {
      "turn_number": 30,
      "time": "2156-05-17 15:00:00",
      "speaker": "Doctor",
      "text": "The infusion went smoothly. You did great. We’ll keep an eye on you for any reactions."
    },
    {
      "turn_number": 31,
      "time": "2156-05-18 09:00:00",
      "speaker": "Patient",
      "text": "I feel okay, but my ostomy output has been watery. Should I be concerned?"
    },
    {
      "turn_number": 32,
      "time": "2156-05-18 09:01:00",
      "speaker": "Doctor",
      "text": "We’re concerned it might be early graft-versus-host disease in the gut. We’re starting budesonide to help calm the inflammation."
    },
    {
      "turn_number": 33,
      "time": "2156-05-18 09:02:00",
      "speaker": "Patient",
      "text": "Is that serious? I’ve heard GVHD can be bad."
    },
    {
      "turn_number": 34,
      "time": "2156-05-18 09:03:00",
      "speaker": "Doctor",
      "text": "This is mild and treatable. We’re catching it early. Most patients respond well to budesonide. We’ll watch your symptoms closely."
    },
    {
      "turn_number": 35,
      "time": "2156-05-19 10:30:00",
      "speaker": "Doctor",
      "text": "Your latest labs show your neutrophil count is starting to rise. That’s a sign your transplant is engrafting."
    },
    {
      "turn_number": 36,
      "time": "2156-05-19 10:31:00",
      "speaker": "Patient",
      "text": "That’s great news! Does that mean I’m getting better?"
    },
    {
      "turn_number": 37,
      "time": "2156-05-19 10:32:00",
      "speaker": "Doctor",
      "text": "It’s a very positive sign. Your body is starting to make new blood cells. We’ll keep supporting you until your counts normalize."
    },
    {
      "turn_number": 38,
      "time": "2156-05-20 14:00:00",
      "speaker": "Patient",
      "text": "My right eye feels blurry. Should I be worried?"
    },
    {
      "turn_number": 39,
      "time": "2156-05-20 14:01:00",
      "speaker": "Doctor",
      "text": "We’ve referred you to ophthalmology. It could be a cataract or something related to your transplant. We’ll get an MRI to check."
    },
    {
      "turn_number": 40,
      "time": "2156-05-21 16:00:00",
      "speaker": "Doctor",
      "text": "The MRI of your brain and orbits is back. No new lymphoma or orbital mass. There is a cataract, which explains the blurry vision."
    },
    {
      "turn_number": 41,
      "time": "2156-05-21 16:02:00",
      "speaker": "Patient",
      "text": "So it’s not cancer? That’s a relief."
    },
    {
      "turn_number": 42,
      "time": "2156-05-21 16:03:00",
      "speaker": "Doctor",
      "text": "No, no signs of lymphoma recurrence. The changes in your nasopharynx are stable and likely inflammatory."
    },
    {
      "turn_number": 43,
      "time": "2156-05-22 09:00:00",
      "speaker": "Patient",
      "text": "My blood sugars have been high again. Is that normal?"
    },
    {
      "turn_number": 44,
      "time": "2156-05-22 09:01:00",
      "speaker": "Doctor",
      "text": "Yes, steroids and stress can raise them. The diabetes team adjusted your insulin—now 50 units of glargine at dinner."
    },
    {
      "turn_number": 45,
      "time": "2156-05-22 09:02:00",
      "speaker": "Patient",
      "text": "I’ll keep checking them. Any update on my tacrolimus level?"
    },
    {
      "turn_number": 46,
      "time": "2156-05-22 09:03:00",
      "speaker": "Doctor",
      "text": "It was a bit high, so we reduced your dose to 0.5 mg twice a day. We’ll recheck it soon."
    },
    {
      "turn_number": 47,
      "time": "2156-05-23 10:00:00",
      "speaker": "Doctor",
      "text": "Your latest blood cultures are negative—no infection. That’s excellent."
    },
    {
      "turn_number": 48,
      "time": "2156-05-23 10:01:00",
      "speaker": "Patient",
      "text": "And my C. diff test? Still negative?"
    },
    {
      "turn_number": 49,
      "time": "2156-05-23 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, and we’ll keep you on vancomycin for now to prevent recurrence, given your immune status."
    },
    {
      "turn_number": 50,
      "time": "2156-05-24 11:00:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray is clear—no pneumonia. You’re doing well overall."
    },
    {
      "turn_number": 51,
      "time": "2156-05-25 15:00:00",
      "speaker": "Patient",
      "text": "I’ve been having more back pain. Can I get something stronger?"
    },
    {
      "turn_number": 52,
      "time": "2156-05-25 15:01:00",
      "speaker": "Doctor",
      "text": "We can give IV dilaudid for breakthrough pain. We’ve kept your methadone and lyrica going, but we’ll adjust as needed."
    },
    {
      "turn_number": 53,
      "time": "2156-05-28 09:30:00",
      "speaker": "Doctor",
      "text": "Your white count is now 5.0—excellent! You’ve engrafted successfully. We’re stopping filgrastim."
    },
    {
      "turn_number": 54,
      "time": "2156-05-28 09:31:00",
      "speaker": "Patient",
      "text": "That’s wonderful. Does this mean I can go home soon?"
    },
    {
      "turn_number": 55,
      "time": "2156-05-28 09:32:00",
      "speaker": "Doctor",
      "text": "We’re getting close. We want to make sure your counts stay stable and your diarrhea improves before discharge."
    },
    {
      "turn_number": 56,
      "time": "2156-05-30 10:00:00",
      "speaker": "Doctor",
      "text": "Your CMV is still negative, and your stool test showed no virus. That’s good news."
    },
    {
      "turn_number": 57,
      "time": "2156-05-30 10:01:00",
      "speaker": "Patient",
      "text": "And the budesonide—is it helping?"
    },
    {
      "turn_number": 58,
      "time": "2156-05-30 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, your ostomy output has normalized. We’ll keep you on budesonide at home and monitor for GVHD."
    },
    {
      "turn_number": 59,
      "time": "2156-06-01 14:00:00",
      "speaker": "Doctor",
      "text": "We’ve scheduled your discharge for June 4th. You’ll go home on tacrolimus, sirolimus, budesonide, and vancomycin."
    },
    {
      "turn_number": 60,
      "time": "2156-06-01 14:01:00",
      "speaker": "Patient",
      "text": "So many meds. Will I need to stay on them forever?"
    },
    {
      "turn_number": 61,
      "time": "2156-06-01 14:02:00",
      "speaker": "Doctor",
      "text": "Not forever. We’ll taper them over time. The vancomycin and antivirals may continue for a few months due to your immune deficiency."
    },
    {
      "turn_number": 62,
      "time": "2156-06-02 09:00:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. Hemoglobin is 8.9, platelets 40,000. We won’t need to transfuse."
    },
    {
      "turn_number": 63,
      "time": "2156-06-02 09:01:00",
      "speaker": "Patient",
      "text": "And my diabetes? Will I stay on insulin?"
    },
    {
      "turn_number": 64,
      "time": "2156-06-02 09:02:00",
      "speaker": "Doctor",
      "text": "For now, yes. We’ll work with endocrinology to adjust as your recovery continues."
    },
    {
      "turn_number": 65,
      "time": "2156-06-03 10:30:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed your discharge plan. You’ll have labs drawn tomorrow and tacrolimus/sirolimus levels checked in a few days."
    },
    {
      "turn_number": 66,
      "time": "2156-06-03 10:31:00",
      "speaker": "Patient",
      "text": "And my follow-up appointments?"
    },
    {
      "turn_number": 67,
      "time": "2156-06-03 10:32:00",
      "speaker": "Doctor",
      "text": "Yes, with transplant, oncology, and your primary team. We’ll make sure everything’s coordinated."
    },
    {
      "turn_number": 68,
      "time": "2156-06-04 11:00:00",
      "speaker": "Doctor",
      "text": "Good morning! You’re doing great. We’re finalizing your discharge. Any last questions?"
    },
    {
      "turn_number": 69,
      "time": "2156-06-04 11:01:00",
      "speaker": "Patient",
      "text": "Just one—how will I know if something goes wrong at home?"
    },
    {
      "turn_number": 70,
      "time": "2156-06-04 11:02:00",
      "speaker": "Doctor",
      "text": "Call us if you have fever, worsening diarrhea, shortness of breath, or blood sugar below 80 or above 300. We’re here for you."
    },
    {
      "turn_number": 71,
      "time": "2156-06-04 11:03:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I really appreciate all your help."
    },
    {
      "turn_number": 72,
      "time": "2156-06-04 11:04:00",
      "speaker": "Doctor",
      "text": "You did great. We’re proud of your progress. Take care, and we’ll see you in clinic soon."
    }
  ],
  "summary": {
    "admission_start": "2156-05-11 13:10:00",
    "admission_end": "2156-06-04 18:21:00",
    "summary_paragraph": "The patient was admitted for an allogeneic matched unrelated donor stem cell transplant as part of a clinical trial for EBV-positive classical Hodgkin lymphoma. She had completed prior chemotherapy and was in remission. A central venous catheter was placed on admission, followed by reduced-intensity conditioning with fludarabine and busulfan. The stem cell infusion occurred on May 17th without complications. Engraftment was achieved by day 28, with rising neutrophil counts. She developed mild gastrointestinal graft-versus-host disease, presenting as watery ostomy output, and was treated with budesonide. Her C. difficile infection was managed with ongoing oral vancomycin due to immunosuppression. Blood glucose was elevated, requiring insulin adjustment by the diabetes team. Tacrolimus and sirolimus levels were monitored and dosed appropriately. She remained infection-free, with negative CMV and blood cultures. She was discharged home on immunosuppressive, antimicrobial, and supportive therapies with close follow-up planned.",
    "problems": [
      "Hodgkin's disease, unspecified type, unspecified site, extranodal and solid organ sites",
      "Common variable immunodeficiency",
      "Neutropenia, unspecified",
      "Intestinal infection due to Clostridium difficile",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Chronic obstructive asthma, unspecified",
      "Iron deficiency anemia, unspecified",
      "Anxiety state, unspecified",
      "Depressive disorder, not elsewhere classified",
      "Unspecified acquired hypothyroidism",
      "Panic disorder without agoraphobia",
      "Esophageal reflux",
      "Acquired absence of intestine (large) (small)",
      "Other chronic pain",
      "Examination of participant in clinical trial"
    ]
  }
}
